ALTER TABLE public.course_groups ADD COLUMN IF NOT EXISTS sales_code text; ALTER TABLE public.course_groups ADD COLUMN IF NOT EXISTS redirect_url text; CREATE UNIQUE INDEX IF NOT EXISTS idx_course_groups_sales_code ON public.course_groups(sales_code) WHERE sales_code IS NOT NULL; DROP FUNCTION IF EXISTS public.get_course_groups_public(uuid); CREATE FUNCTION public.get_course_groups_public(_course_id uuid) RETURNS TABLE(id uuid, name text, price_clp integer, is_default boolean, sales_code text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT g.id, g.name, g.price_clp, g.is_default, g.sales_code FROM public.course_groups g JOIN public.courses c ON c.id = g.course_id WHERE g.course_id = _course_id AND (c.status = 'published' OR c.creator_id = auth.uid() OR public.has_role(auth.uid(), 'admin')) ORDER BY g.is_default DESC, g.created_at ASC; $$; REVOKE ALL ON FUNCTION public.get_course_groups_public(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_course_groups_public(uuid) TO anon, authenticated; CREATE OR REPLACE FUNCTION public.prevent_creator_reviews_reassignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.creator_id IS DISTINCT FROM OLD.creator_id THEN RAISE EXCEPTION 'creator_id cannot be changed'; END IF; RETURN NEW; END; $$; CREATE OR REPLACE FUNCTION public.prevent_creator_review_reassign() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.creator_id IS DISTINCT FROM OLD.creator_id THEN RAISE EXCEPTION 'creator_id cannot be changed'; END IF; RETURN NEW; END; $$;